import React from "react";
import { PieChart, Pie, Cell } from "recharts";

const COLORS = ["#3b82f6", "#e5e7eb"];

const GoalCard = ({ goal, onRemove }) => {
  const percent = Math.min((goal.saved / goal.amount) * 100, 100);
  const data = [
    { name: "Saved", value: percent },
    { name: "Remaining", value: 100 - percent },
  ];

  return (
    <div className="bg-card rounded-xl shadow p-6 flex flex-col items-center relative">
      <button
        className="absolute top-3 right-3 text-xs text-gray-400 hover:text-red-500"
        onClick={() => onRemove(goal.id)}
        title="Remove Goal"
      >
        ×
      </button>
      <PieChart width={80} height={80} className="mb-4">
        <Pie
          data={data}
          cx={40}
          cy={40}
          innerRadius={28}
          outerRadius={36}
          startAngle={90}
          endAngle={-270}
          dataKey="value"
        >
          {data.map((entry, idx) => (
            <Cell key={`cell-${idx}`} fill={COLORS[idx]} />
          ))}
        </Pie>
      </PieChart>
      <div className="text-lg font-semibold mb-1">{goal.name}</div>
      <div className="text-xs text-gray-400 mb-2">By {goal.deadline}</div>
      <div className="w-full mb-2">
        <div className="flex justify-between text-xs mb-1">
          <span>${goal.saved.toLocaleString()} saved</span>
          <span>${goal.amount.toLocaleString()} target</span>
        </div>
        <div className="w-full h-2 bg-gray-100 rounded">
          <div
            className="h-2 bg-primary rounded"
            style={{ width: `${percent}%` }}
          ></div>
        </div>
      </div>
      {goal.monthlySavings !== undefined && (
        <div className="mt-2 text-xs bg-blue-50 text-primary px-3 py-1 rounded-full font-medium">
          Save ${goal.monthlySavings.toLocaleString()} / month
        </div>
      )}
    </div>
  );
};

export default GoalCard;
